/**
 * Stage 19: the scientific concept index.
 *
 * One typed, local list of concepts. A concept is a scientific idea with a short explanation and ONE real destination (a
 * subject + tool that exists in the subject registry). Tools themselves are not duplicated here: `buildToolEntries()` derives
 * them from `SUBJECT_TOOLS`, so a renamed or removed tool cannot leave a stale search result. `validateConceptIndex()` reports
 * every concept whose destination or related concept does not exist (tests run it, and the UI never lists an invalid one).
 *
 * Explanations are deliberately short, textbook-level statements. No source references are listed because none were
 * independently checked for these summaries (see `sources`, which stays empty unless a reference was verified).
 */
import { SUBJECTS, SUBJECT_TOOLS, isAvailable, type SubjectId } from "../../navigation/subjects";

export interface ConceptDestination { subject: SubjectId; toolId: string }

export interface Concept {
  id: string;
  name: string;
  subject: SubjectId;
  /** One or two sentences, scientifically conservative. */
  summary: string;
  aliases: string[];
  /** Words that make a concept relevant without being a name for it (e.g. "ATP" for the citric acid cycle). */
  relatedTerms: string[];
  /** Why a related term is relevant, shown in the result (keyed by the related term as written). */
  termNotes?: Record<string, string>;
  destination: ConceptDestination;
  related: string[];
  /** Verified references only. Empty means "not independently referenced". */
  sources?: string[];
}

const c = (concept: Concept): Concept => concept;

