// ---- tool entries (derived) ---------------------------------------------------------------------------------------------

export interface ToolEntry {
  id: string;
  name: string;
  subject: SubjectId;
  summary: string;
  destination: ConceptDestination;
}

/** One entry per working tool in the subject registry (Overview and Saved pages included so they are reachable, but flagged). */
export function buildToolEntries(): ToolEntry[] {
  const entries: ToolEntry[] = [];
  for (const subject of SUBJECTS) {
    if (!isAvailable(subject.id)) continue;
    for (const tool of SUBJECT_TOOLS[subject.id]) {
      entries.push({ id: `tool:${subject.id}:${tool.id}`, name: tool.label, subject: subject.id, summary: tool.summary, destination: { subject: subject.id, toolId: tool.id } });
    }
  }
  return entries;
}

export const TOOL_ENTRIES: ToolEntry[] = buildToolEntries();

/** Whether a destination names a tool that really exists in an available subject. */
export function isValidDestination(destination: ConceptDestination | null | undefined): boolean {
  if (!destination) return false;
  if (!SUBJECTS.some((subject) => subject.id === destination.subject) || !isAvailable(destination.subject)) return false;
  return SUBJECT_TOOLS[destination.subject].some((tool) => tool.id === destination.toolId);
}

export function getConcept(id: string): Concept | undefined {
  return CONCEPTS.find((concept) => concept.id === id);
}

/** Problems with an index (default: the shipped one). Empty means every destination and relation is real. */
export function validateConceptIndex(concepts: readonly Concept[] = CONCEPTS): string[] {
  const problems: string[] = [];
  const ids = new Set<string>();
  for (const concept of concepts) {
    if (ids.has(concept.id)) problems.push(`duplicate concept id ${concept.id}`);
    ids.add(concept.id);
    if (!concept.name.trim() || !concept.summary.trim()) problems.push(`${concept.id}: empty name or summary`);
    if (!isValidDestination(concept.destination)) problems.push(`${concept.id}: destination ${concept.destination.subject}/${concept.destination.toolId} is not a real tool`);
    if (concept.destination.subject !== concept.subject) problems.push(`${concept.id}: subject differs from its destination subject`);
    for (const note of Object.keys(concept.termNotes ?? {})) {
      if (!concept.relatedTerms.includes(note) && !concept.aliases.includes(note)) problems.push(`${concept.id}: term note "${note}" names no related term`);
    }
  }
  for (const concept of concepts) {
    for (const other of concept.related) {
      if (!ids.has(other)) problems.push(`${concept.id}: related concept ${other} does not exist`);
      if (other === concept.id) problems.push(`${concept.id}: relates to itself`);
    }
  }
  return problems;
}
